--刷新队列列表
function UIFishPoolHangUpDialog:RefreshQueueList()
    if self._isInitList then
        GameUtils.ReloadData(self.CommonHangUpTeams, table.count(self._allFishHangUpQueueId))
    else
        self.CommonHangUpTeams:InitListView(table.count(self._allFishHangUpQueueId), Bind(self, self.OnRefreshIndex))
        self._isInitList = true
    end
end

function UIFishPoolHangUpDialog:OnRefreshIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local id = self._allFishHangUpQueueId[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolHangUpQueueNode)
    if scr then
        scr:Refresh(id, function()
            self:ChooseQueue(id)
        end)

        local ind = table.keyof(self._allFishHangUpQueueId, self._curSelectQueueId)
        scr:RefreshSelectActive(checkNumber(ind) == index + 1)
    end
    return cell
end

--选择队列
function UIFishPoolHangUpDialog:ChooseQueue(queueId)
    queueId = checkNumber(queueId)
    local go
    local lastSelectInd = table.keyof(self._allFishHangUpQueueId, self._curSelectQueueId)
    if checkNumber(lastSelectInd) > 0 then
        go = self.CommonHangUpTeams:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFishPoolHangUpQueueNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
                lastScr:FillCards()
            end
        end
    end

    self._curSelectQueueId = queueId
    local curSelectInd = table.keyof(self._allFishHangUpQueueId, self._curSelectQueueId)
    if checkNumber(curSelectInd) > 0 then
        go = self.CommonHangUpTeams:GetShownItemByItemIndex(curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFishPoolHangUpQueueNode)
            if curScr then
                curScr:RefreshSelectActive(true)
            end
        end
    end

    self:CheckRightStatus()
end



--绘制渔场信息
function UIFishPoolHangUpDialog:FillAllFishPlaceList()
    if not self._isInitFishPlace then
        self._allFishPlaceVo = {}
        local t = FishingUtils.GetAllFishPlace()
        if t then
            self._allFishPlaceVo = t
        end
        self.loopviewList:InitGridView(table.count(self._allFishPlaceVo), Bind(self, self.OnRefreshPlaceIndex))
        self._isInitFishPlace = true
    else
        GameUtils.ReloadData(self.loopviewList, table.count(self._allFishPlaceVo))
    end
end

function UIFishPoolHangUpDialog:OnRefreshPlaceIndex(listView, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local data = self._allFishPlaceVo[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIFishPoolHangUpPlaceNode)
    if scr then
        scr:Refresh(data, function()
            local isUnlock, err = FishingUtils.IsCanFishHangUp(data.id)
            if not isUnlock then
                GameUtils.Toast(err)
                return
            end
            local isTasking = FishingUtils.IsFishPlaceHasTask(data.id)
            if isTasking then
                GameUtils.Toast(localize("该渔场已有任务"))
                return
            end

            self._curSelectFishPlaceId = checkNumber(data.id)
            self:CheckRightStatus()
        end)
    end
    return cell
end

--设置信息
function UIFishPoolHangUpDialog:FillFishSettingInfo()
    local scr = CfUtils.GetLuaScr(self.Group2, UIFishPoolHangUpSettingInfoNode)
    if scr then
        scr:Refresh(self._curSelectQueueId, self._curSelectFishPlaceId, function()
            self._curSelectFishPlaceId = 0
            self:CheckRightStatus()
        end, function(num)
            local t = FishingUtils.GetHangUpConsumeEnergyData(self._curSelectQueueId, num)
            --print(table.dump(t))
            local curSelectInd = table.keyof(self._allFishHangUpQueueId, self._curSelectQueueId)
            if checkNumber(curSelectInd) > 0 then
                local go = self.CommonHangUpTeams:GetShownItemByItemIndex(curSelectInd - 1)
                if go then
                    local curScr = CfUtils.GetLuaScr(go, UIFishPoolHangUpQueueNode)
                    if curScr then
                        curScr:FillCards(t)
                    end
                end
            end
        end)
    end
end

--任务信息
function UIFishPoolHangUpDialog:FillFishTaskInfo()
    local scr = CfUtils.GetLuaScr(self.Group1, UIFishPoolHangUpTaskInfoNode)
    if scr then
        scr:Refresh(self._curSelectQueueId)
    end
end

function UIFishPoolHangUpDialog:CheckRightStatus()
    if checkNumber(self._curSelectQueueId) == 0 then
        self:RefreshRightInfo(QueueType.None)
    else
        --刷新右边信息
        local isHaveTask = FishingUtils.IsHangeUpQueueHasTask(self._curSelectQueueId)
        if isHaveTask then
            self:RefreshRightInfo(QueueType.TaskFinish)
        else
            self:RefreshRightInfo(QueueType.Free)
        end
    end
end

--刷新右边信息
function UIFishPoolHangUpDialog:RefreshRightInfo(status)
    status = checkNumber(status)
    KTool.SetActive(self.Group1, (status == QueueType.TaskFinish or status == QueueType.Tasking))
    KTool.SetActive(self.Group2, (status == QueueType.Free and checkNumber(self._curSelectFishPlaceId) > 0))
    KTool.SetActive(self.Group3, (status == QueueType.Free and checkNumber(self._curSelectFishPlaceId) == 0))
    KTool.SetActive(self.EmptyNode, (status == QueueType.None))

    if (status == QueueType.TaskFinish or status == QueueType.Tasking) then
        self:FillFishTaskInfo()
    elseif (status == QueueType.Free and checkNumber(self._curSelectFishPlaceId) > 0) then
        self:FillFishSettingInfo()
    elseif (status == QueueType.Free and checkNumber(self._curSelectFishPlaceId) == 0) then
        self:FillAllFishPlaceList()
    end
end

function UIFishPoolHangUpDialog:OnFishBasketChange()
    self._curSelectFishPlaceId = 0   --清空一次选择
    self:FillSelf()
end

