---RefeshEntrustRedPointNum  队列是否有奖励可领取
function UIFishPoolHangUpDialog:RefeshRedPointNum()
    local t = fishingComponent:GetFishTeamInfo()
    if not t then
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishHangUp, 0)
        return -1
    end

    local _time
    for k, v in pairs(t) do
        if FishingUtils.IsHangeUpQueueHasTask(v.teamId) then
            --有待领取的 直接亮
            if FishingUtils.IsHangeUpQueueTaskFinish(v.teamId) then
                GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishHangUp, 1)
                return 0
            else
                local activeTime = checkNumber((v.remainTime))
                activeTime = (activeTime > 0 and activeTime or 0)
                if _time and activeTime < _time then
                    _time = activeTime
                elseif not _time then
                    _time = activeTime
                end
            end
        end
    end
    if _time then
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.RedPointMgrComponent)
        comp:UpdateRedPointData({
            fishingOffline = checkNumber(_time)
        })
    else
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishHangUp, 0)
    end
    
    return checkNumber(_time)
end

function UIFishPoolHangUpDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RefeshRedPointNum()
        Events.RemoveListener(Constants.EventNames.FishBasketChange, self.EventFishBasketChange)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishPoolHangUpDialog
